(function(root){
const KEY='billow-ai-endpoint',TOKEN='billow-ai-access';
function config(){try{return {endpoint:localStorage.getItem(KEY)||'',token:sessionStorage.getItem(TOKEN)||''}}catch{return {endpoint:'',token:''}}}
function setConfig(endpoint,token){endpoint=endpoint.trim().replace(/\/+$/,'');if(endpoint){const url=new URL(endpoint);if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash||url.pathname!=='/'||!url.hostname.endsWith('.workers.dev'))throw Error('Use the https://…workers.dev address from setup.');}if(token&&token.length<32)throw Error('Use the private planner access code from setup, not your OpenAI key.');if(token.startsWith('sk-'))throw Error('Do not enter your OpenAI key here. Use the planner access code.');localStorage.setItem(KEY,endpoint);if(token)sessionStorage.setItem(TOKEN,token);else sessionStorage.removeItem(TOKEN);}
function ready(){const c=config();return !!(c.endpoint&&c.token)}
async function plan(date,morning,fixed){const c=config();if(!ready())throw Error('Connect your AI planner in Settings first.');const response=await fetch(c.endpoint+'/plan',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+c.token},body:JSON.stringify({date,morning:{must:morning.must,wake:morning.wake||'11:00',finish:morning.finish||'23:00',energy:morning.energy||3,place:morning.place||''},fixed:fixed.map(({id,title,start,duration,type})=>({id,title,start,duration,type}))}),signal:AbortSignal.timeout(55000)});let result;try{result=await response.json()}catch{throw Error('The planner returned an unreadable response.')}if(!response.ok)throw Error(result.error||'Could not generate a plan.');if(!result||!Array.isArray(result.blocks)||!Array.isArray(result.tasks)||!Array.isArray(result.reasons)||!Array.isArray(result.unscheduled)||root.Planner.conflicts(result.blocks).length)throw Error('The planner returned an invalid schedule.');for(const b of fixed){const found=result.blocks.find(x=>x.id===b.id);if(!found||found.start!==b.start||found.duration!==b.duration||found.title!==b.title||found.type!=='fixed')throw Error('A fixed commitment changed. Please try again.');}return result;}
root.AIPlanner={config,setConfig,ready,plan};
})(window);
